import * as THREE from '../../vendor/three.module.js';
import {seededRandom} from './simulation.js';
export function createEffects(scene,quality='high'){
 const random=seededRandom(741);const root=new THREE.Group();root.name='pooled combat VFX';scene.add(root);const cap=quality==='low'?120:quality==='medium'?360:640,states=Array.from({length:cap},()=>({life:0,x:0,y:0,z:0,vx:0,vy:0,vz:0,max:1}));let cursor=0;
 const particleGeo=new THREE.OctahedronGeometry(.045,0),particleMat=new THREE.MeshBasicMaterial({vertexColors:true,toneMapped:false});const particles=new THREE.InstancedMesh(particleGeo,particleMat,cap);particles.instanceMatrix.setUsage(THREE.DynamicDrawUsage);particles.frustumCulled=false;root.add(particles);
 const dummy=new THREE.Object3D(),color=new THREE.Color(),up=new THREE.Vector3(0,1,0),direction=new THREE.Vector3(),normal=new THREE.Vector3(0,0,1);
 for(let i=0;i<cap;i++){dummy.scale.setScalar(0);dummy.updateMatrix();particles.setMatrixAt(i,dummy.matrix);particles.setColorAt(i,color.setHex(0xff9944));}
 const beamGeo=new THREE.CylinderGeometry(1,1,1,10,1,true),beamMats=[false,true].map(core=>new THREE.ShaderMaterial({transparent:true,blending:THREE.AdditiveBlending,depthWrite:false,toneMapped:false,uniforms:{age:{value:0},clock:{value:0},core:{value:core?1:0}},vertexShader:`varying vec2 v;varying vec3 n;varying vec3 eye;void main(){v=uv;vec4 p=modelViewMatrix*vec4(position,1.);n=normalize(normalMatrix*normal);eye=-p.xyz;gl_Position=projectionMatrix*p;}`,fragmentShader:`varying vec2 v;varying vec3 n;varying vec3 eye;uniform float age,clock,core;void main(){float facing=pow(abs(dot(normalize(n),normalize(eye))),.7);float ripple=.75+.25*sin(v.y*140.-clock*95.+sin(v.x*30.));float ends=smoothstep(0.,.035,v.y)*(1.-smoothstep(.965,1.,v.y));vec3 color=mix(vec3(.025,.30,1.8),vec3(1.5,2.1,2.6),core);float a=(1.-age)*ends*facing*mix(.34,.86,core)*mix(ripple,1.,core);gl_FragColor=vec4(color,a);}`}));
 const beams=Array.from({length:24},()=>{const group=new THREE.Group();group.visible=false;root.add(group);const b={group,life:0,max:.18};for(const mat of beamMats){const m=new THREE.Mesh(beamGeo,mat);m.onBeforeRender=()=>{mat.uniforms.age.value=1-Math.max(0,b.life/b.max);mat.uniforms.clock.value=beamTime;mat.uniformsNeedUpdate=true;};group.add(m);}return b;});let beamCursor=0,beamTime=0;
 const ringGeo=new THREE.TorusGeometry(1,.012,5,40,Math.PI*1.65),ringMat=new THREE.MeshBasicMaterial({color:0x168cff,transparent:true,opacity:.65,blending:THREE.AdditiveBlending,depthWrite:false,toneMapped:false});
 const rings=Array.from({length:12},()=>{const mesh=new THREE.Mesh(ringGeo,ringMat.clone());mesh.visible=false;root.add(mesh);return {mesh,life:0,max:1,power:1};});let ringCursor=0;
 const canvas=document.createElement('canvas');canvas.width=128;canvas.height=128;const ctx=canvas.getContext('2d'),g=ctx.createRadialGradient(64,64,0,64,64,64);g.addColorStop(0,'rgba(185,235,255,1)');g.addColorStop(.08,'rgba(40,145,255,.8)');g.addColorStop(.35,'rgba(0,60,255,.20)');g.addColorStop(1,'rgba(0,0,255,0)');ctx.fillStyle=g;ctx.fillRect(0,0,128,128);const texture=new THREE.CanvasTexture(canvas);
 const bursts=Array.from({length:12},()=>{const material=new THREE.SpriteMaterial({map:texture,color:0x339dff,transparent:true,blending:THREE.AdditiveBlending,depthWrite:false,toneMapped:false});const mesh=new THREE.Sprite(material);mesh.visible=false;root.add(mesh);return {mesh,material,life:0,max:.2,power:1};});let burstCursor=0;
 const arcs=Array.from({length:quality==='low'?4:12},()=>{const geometry=new THREE.BufferGeometry(),positions=new Float32Array(8*6*6);geometry.setAttribute('position',new THREE.BufferAttribute(positions,3).setUsage(THREE.DynamicDrawUsage));const material=new THREE.LineBasicMaterial({color:0x178fff,transparent:true,opacity:1,blending:THREE.AdditiveBlending,depthWrite:false,toneMapped:false});const mesh=new THREE.LineSegments(geometry,material);mesh.visible=false;mesh.frustumCulled=false;root.add(mesh);return {mesh,geometry,material,positions,life:0,max:.3};});let arcCursor=0;
 function burst(pos,power,muzzle=false){const b=bursts[burstCursor++%bursts.length];b.life=b.max=.16+power*.035;b.power=power;b.muzzle=muzzle;b.mesh.position.copy(pos);b.mesh.visible=true;}
 function ring(pos,dir,power,local=false){const r=rings[ringCursor++%rings.length];r.life=r.max=local?.11:.28+power*.07;r.power=power;r.local=local;r.mesh.position.copy(pos);r.mesh.quaternion.setFromUnitVectors(normal,dir.clone().normalize());r.mesh.visible=true;r.mesh.scale.setScalar(.05);}
 function electric(pos,power){const a=arcs[arcCursor++%arcs.length];a.life=a.max=.20+power*.07;a.mesh.position.copy(pos);a.mesh.visible=true;let k=0;for(let arm=0;arm<8;arm++){const az=arm*Math.PI/4,v=new THREE.Vector3(Math.cos(az),Math.sin(az)*.8,.25*Math.sin(arm*2)),prev=new THREE.Vector3();for(let j=1;j<=6;j++){const next=v.clone().multiplyScalar(j*.10*power);next.x+=(random()-.5)*.14*power;next.y+=(random()-.5)*.14*power;next.z+=(random()-.5)*.16*power;a.positions.set([prev.x,prev.y,prev.z,next.x,next.y,next.z],k);k+=6;prev.copy(next);}}a.geometry.attributes.position.needsUpdate=true;}
 function sparks(pos,count,power=1,tint=0xff9944){for(let i=0;i<count;i++){const s=states[cursor];s.life=.2+random()*.65;s.max=s.life;s.x=pos.x;s.y=pos.y;s.z=pos.z;s.vx=(random()-.5)*power*7;s.vy=(random()*.8+.2)*power*5;s.vz=(random()-.5)*power*7;particles.setColorAt(cursor,color.setHex(tint));cursor=(cursor+1)%cap;}particles.instanceColor.needsUpdate=true;}
 function beam(start,end,power=1){const b=beams[beamCursor++%beams.length],len=start.distanceTo(end);b.life=.15+power*.03;b.max=b.life;b.group.visible=true;b.group.scale.set(1,1,1);b.group.position.copy(start).lerp(end,.5);direction.subVectors(end,start).normalize();b.group.quaternion.setFromUnitVectors(up,direction);b.group.children[0].scale.set(.06*power,len,.06*power);b.group.children[1].scale.set(.012*power,len,.012*power);burst(start,power*.75,true);ring(start,direction,power*.04,true);if(power>1.5)ring(start.clone().lerp(end,.12),direction,power*.05,true);}
 function impact(pos,dir,power=1){sparks(pos,Math.floor(12*power),power,0x38adff);sparks(pos,Math.floor(10*power),power*.7,0xffb56a);burst(pos,power);electric(pos,power);ring(pos,dir,power*.6);}
 function explode(pos,power=1){sparks(pos,Math.min(100,Math.floor(42*power)),power,0xffa34e);sparks(pos,Math.floor(18*power),power,0x168cff);burst(pos,power*1.5);electric(pos,power*1.3);ring(pos,up,power);ring(pos,normal,power*.7);}
 function update(dt,time){beamTime=time;for(let i=0;i<cap;i++){const s=states[i];if(s.life>0){s.life-=dt;s.vy-=dt*7;s.x+=s.vx*dt;s.y+=s.vy*dt;s.z+=s.vz*dt;if(s.y<.03){s.y=.03;s.vy=Math.abs(s.vy)*.25;s.vx*=.85;s.vz*=.85;}dummy.position.set(s.x,s.y,s.z);direction.set(s.vx,s.vy,s.vz).normalize();dummy.quaternion.setFromUnitVectors(up,direction);const fade=Math.max(0,s.life/s.max);dummy.scale.set(fade*.6,fade*(1+Math.min(3,Math.hypot(s.vx,s.vy,s.vz)*.12)),fade*.6);}else dummy.scale.setScalar(0);dummy.updateMatrix();particles.setMatrixAt(i,dummy.matrix);}particles.instanceMatrix.needsUpdate=true;
  for(const b of beams)if(b.life>0){b.life-=dt;b.group.visible=b.life>0;const f=Math.max(.02,b.life/b.max);b.group.scale.set(f,1,f);}
  for(const r of rings)if(r.life>0){r.life-=dt;r.mesh.visible=r.life>0;r.mesh.material.opacity=Math.pow(Math.max(0,r.life/r.max),r.local?2:1)*(r.local?.26:.45);r.mesh.scale.setScalar(.05+(1-r.life/r.max)*r.power*2);}
  for(const b of bursts)if(b.life>0){b.life-=dt;b.mesh.visible=b.life>0;const f=Math.max(0,b.life/b.max);b.material.opacity=f;b.mesh.scale.setScalar((b.muzzle?.13+b.power*.055:.35+b.power*.25)*(1.4-f*.4));}
  for(const a of arcs)if(a.life>0){a.life-=dt;a.mesh.visible=a.life>0;a.material.opacity=Math.max(0,a.life/a.max);a.mesh.rotation.z+=dt*1.2;}
 }
 function dispose(){scene.remove(root);particleGeo.dispose();particleMat.dispose();beamGeo.dispose();beamMats.forEach(m=>m.dispose());ringGeo.dispose();ringMat.dispose();rings.forEach(r=>r.mesh.material.dispose());texture.dispose();bursts.forEach(b=>b.material.dispose());arcs.forEach(a=>{a.geometry.dispose();a.material.dispose();});particles.dispose();root.clear();}
 return {beam,impact,explode,update,dispose,root,stats:()=>({particles:states.filter(s=>s.life>0).length,beams:beams.filter(s=>s.life>0).length})};
}
